package main

// reference.go replaces three Go standard-library calls that do not behave like
// the Python methods validate.py uses. These tests walk the whole code point space
// against Python's own data, so a regenerated table, a Go upgrade or a mistake in
// the Final_Sigma rule cannot pass silently.
//
// Expectations come from testdata/unicode_vectors.json, generated by
// testdata/make_unicode.py, which also writes unicode_tables.go.

import (
	"encoding/json"
	"os"
	"sort"
	"strconv"
	"strings"
	"testing"
)

type unicodeVectors struct {
	UnicodeVersion string            `json:"unicode_version"`
	Whitespace     []int             `json:"whitespace"`
	Cased          [][]int           `json:"cased"`
	CaseIgnorable  [][]int           `json:"case_ignorable"`
	Lower          map[string]string `json:"lower"`
	Probes         []struct {
		Input string `json:"input"`
		Lower string `json:"lower"`
	} `json:"probes"`
}

func loadUnicodeVectors(t *testing.T) unicodeVectors {
	t.Helper()
	data, err := os.ReadFile("testdata/unicode_vectors.json")
	if err != nil {
		t.Fatalf("read unicode vectors: %v", err)
	}
	var vectors unicodeVectors
	if err := json.Unmarshal(data, &vectors); err != nil {
		t.Fatalf("parse unicode vectors: %v", err)
	}
	if len(vectors.Whitespace) == 0 || len(vectors.Lower) == 0 || len(vectors.Probes) == 0 {
		t.Fatal("unicode vectors are empty")
	}
	return vectors
}

func decodeRunes(t *testing.T, spaced string) string {
	t.Helper()
	var builder strings.Builder
	for _, field := range strings.Fields(spaced) {
		unit, err := strconv.ParseUint(field, 16, 32)
		if err != nil {
			t.Fatalf("bad code point %q: %v", field, err)
		}
		builder.WriteRune(rune(unit))
	}
	return builder.String()
}

func spanContains(spans [][]int, point rune) bool {
	index := sort.Search(len(spans), func(i int) bool { return rune(spans[i][1]) >= point })
	return index < len(spans) && point >= rune(spans[index][0])
}

func TestReferenceSpaceEveryRune(t *testing.T) {
	vectors := loadUnicodeVectors(t)
	whitespace := map[rune]bool{}
	for _, point := range vectors.Whitespace {
		whitespace[rune(point)] = true
	}
	eachRune(func(point rune) {
		if referenceSpace(point) != whitespace[point] {
			t.Fatalf("U+%04X: impl2 says space=%v, Python says space=%v",
				point, referenceSpace(point), whitespace[point])
		}
		if got := referenceTrimSpace(string(point)); got != "" && whitespace[point] {
			t.Fatalf("U+%04X: strip left %q", point, got)
		}
	})
}

func TestReferenceCasedEveryRune(t *testing.T) {
	vectors := loadUnicodeVectors(t)
	eachRune(func(point rune) {
		if referenceCased(point) != spanContains(vectors.Cased, point) {
			t.Fatalf("U+%04X: impl2 says cased=%v, Python says cased=%v",
				point, referenceCased(point), spanContains(vectors.Cased, point))
		}
		if referenceCaseIgnorable(point) != spanContains(vectors.CaseIgnorable, point) {
			t.Fatalf("U+%04X: impl2 says case-ignorable=%v, Python says %v",
				point, referenceCaseIgnorable(point), spanContains(vectors.CaseIgnorable, point))
		}
	})
}

func TestReferenceLowerEveryRune(t *testing.T) {
	vectors := loadUnicodeVectors(t)
	folds := map[rune]string{}
	for point, spaced := range vectors.Lower {
		value, err := strconv.ParseUint(point, 16, 32)
		if err != nil {
			t.Fatalf("bad code point %q: %v", point, err)
		}
		folds[rune(value)] = decodeRunes(t, spaced)
	}
	eachRune(func(point rune) {
		want, ok := folds[point]
		if !ok {
			want = string(point)
		}
		if got := referenceLower(string(point)); got != want {
			t.Fatalf("U+%04X: impl2 gives %q, Python gives %q", point, got, want)
		}
	})
}

func TestReferenceLowerProbes(t *testing.T) {
	vectors := loadUnicodeVectors(t)
	for _, probe := range vectors.Probes {
		if got := referenceLower(probe.Input); got != probe.Lower {
			t.Errorf("lower(%q):\n got %q\nwant %q", probe.Input, got, probe.Lower)
		}
	}
}

// TestFinalSigmaContext covers the rule itself rather than the tables: the same
// capital sigma must lower differently depending on what surrounds it.
func TestFinalSigmaContext(t *testing.T) {
	cases := []struct{ input, want string }{
		{"Σ", "σ"},
		{"ΟΣ", "ος"},
		{"ΣΣ", "σς"},
		{"ΣΣΣ", "σσς"},
		{"ΑΣΑ", "ασα"},
		{"ΟΔΟΣ", "οδος"},
		{"ΟΔΟΣ ΟΔΟΣ", "οδος οδος"},
		{"ΑΣ'Α", "ασ'α"},
		{"ΑΣ'Σ", "ασ'ς"},
		{"ΑΣ\u00adΑ", "ασ\u00adα"},
		{"ΑΣ\u0301Α", "ασ\u0301α"},
		{"ΑΣ Α", "ας α"},
		{"ΣΑ", "σα"},
		{"'Σ", "'σ"},
		{"\u0301Σ", "\u0301σ"},
	}
	for _, item := range cases {
		if got := referenceLower(item.input); got != item.want {
			t.Errorf("lower(%q) = %q, want %q", item.input, got, item.want)
		}
	}
}

func TestReferenceTrimSpaceProbes(t *testing.T) {
	cases := []struct{ input, want string }{
		{"", ""},
		{"  padded  ", "padded"},
		{"\x1cpadded\x1f", "padded"},
		{"\u00a0padded\u2007", "padded"},
		{"\t\n\v\f\r padded \t\n\v\f\r", "padded"},
		{"\u2028padded\u2029", "padded"},
		{"padded", "padded"},
		{"\x1c\x1d\x1e\x1f", ""},
		{"\u0085", ""},
		{"a\u00a0", "a"},
	}
	for _, item := range cases {
		if got := referenceTrimSpace(item.input); got != item.want {
			t.Errorf("strip(%q) = %q, want %q", item.input, got, item.want)
		}
	}
}
